import React, { useState } from 'react';
import axios from 'axios';
import './Login.css';
import { useNavigate } from 'react-router-dom';
import Bubbles from '../Bubbles';

const Login = () => {
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [response, setResponse] = useState(null);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await axios.post(`${process.env.REACT_APP_API_BASE_URL}/login`, {
        phone,
        password,
      });

      const { data } = res;
      setResponse(data);

      localStorage.setItem('authToken', data.token);
      localStorage.setItem('educationalLevelId', data.user.educational_level_id);
      localStorage.setItem('id', data.user.id);

      navigate('/Teachers');
      console.log('Login Success:', data);
    } catch (error) {
      setError('Login Failed: برجاء التاكد من الايميل او كلمه السر 🚫');
      console.error('Login Failed:', error.response ? error.response.data : error.message);
    } finally {
      setLoading(false);
    }
  };

  const BachHome = () => {
    navigate('/');
  };

  return (
    <div className="login-page">
      <div className="login-card animiL">
        <h2 className="login-title">Log In</h2>
        <p className="login-subtitle">
          Don't have an Account? <a href="/Signup">Create Account</a>
        </p>

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Mobile Number</label>
            <input
              type="text"
              placeholder="010000000"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label>Password</label>
            <input
              type="password"
              placeholder="Enter password here"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
            />
          </div>

          <button
            type="submit"
            className="btn-login"
            disabled={loading}
            style={{ position: 'relative', minHeight: '44px' }}
          >
            {loading ? (
              <div style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: '100%',
                height: '100%'
              }}>
                <div className="loader" style={{
                  width: '24px',
                  height: '24px',
                  marginRight: '8px'
                }}></div>
                <span style={{ fontFamily: 'Arial, sans-serif' }}>جاري التحقق...</span>
              </div>
            ) : (
              'Log In'
            )}
          </button>

          <button
            type="button"
            className="btn-home"
            onClick={BachHome}
            disabled={loading}
          >
            الرئيسيه
          </button>
        </form>

        {response && <div className="response success">Login Successful 🎉</div>}
        {error && <div className="response error">{error}</div>}
      </div>

      {/* Add the loader CSS */}
      <style>
        {`
          .loader {
            transform: rotateZ(45deg);
            perspective: 1000px;
            border-radius: 50%;
            width: 48px;
            height: 48px;
            color: #fff;
          }
          .loader:before,
          .loader:after {
            content: '';
            display: block;
            position: absolute;
            top: 0;
            left: 0;
            width: inherit;
            height: inherit;
            border-radius: 50%;
            transform: rotateX(70deg);
            animation: 1s spin linear infinite;
          }
          .loader:after {
            color: #FF3D00;
            transform: rotateY(70deg);
            animation-delay: .4s;
          }

          @keyframes rotate {
            0% {
              transform: translate(-50%, -50%) rotateZ(0deg);
            }
            100% {
              transform: translate(-50%, -50%) rotateZ(360deg);
            }
          }

          @keyframes rotateccw {
            0% {
              transform: translate(-50%, -50%) rotate(0deg);
            }
            100% {
              transform: translate(-50%, -50%) rotate(-360deg);
            }
          }

          @keyframes spin {
            0%,
            100% {
              box-shadow: .2em 0px 0 0px currentcolor;
            }
            12% {
              box-shadow: .2em .2em 0 0 currentcolor;
            }
            25% {
              box-shadow: 0 .2em 0 0px currentcolor;
            }
            37% {
              box-shadow: -.2em .2em 0 0 currentcolor;
            }
            50% {
              box-shadow: -.2em 0 0 0 currentcolor;
            }
            62% {
              box-shadow: -.2em -.2em 0 0 currentcolor;
            }
            75% {
              box-shadow: 0px -.2em 0 0 currentcolor;
            }
            87% {
              box-shadow: .2em -.2em 0 0 currentcolor;
            }
          }
          
          .btn-login:disabled {
            opacity: 0.9;
            cursor: wait;
          }
          
          .btn-home:disabled {
            opacity: 0.7;
            cursor: not-allowed;
          }
          
          input:disabled {
            background-color: #f5f5f5;
            cursor: not-allowed;
          }
        `}
      </style>
    </div>
  );
};

export default Login;